# ALL input 2s stay in the same column when sorted by column!
# This is a very important observation

# Let me verify this across all positions
input_by_col = {}
output_by_col = {}

for pr, pc in input_positions:
    input_by_col.setdefault(pc, []).append(pr)
for pr, pc in output_positions:
    output_by_col.setdefault(pc, []).append(pr)

print("2s by column in INPUT:")
for pc in sorted(input_by_col.keys()):
    rows = input_by_col[pc]
    print(f"  Col {pc}: {len(rows)} 2s at rows {sorted(rows)}")

print("\n2s by column in OUTPUT:")
for pc in sorted(output_by_col.keys()):
    rows = output_by_col[pc]
    print(f"  Col {pc}: {len(rows)} 2s at rows {sorted(rows)}")

# Now let's see the mapping within each column
print("\nPer-column row analysis:")
for pc in sorted(input_by_col.keys()):
    inp_rows = sorted(input_by_col[pc])
    if pc in output_by_col:
        out_rows = sorted(output_by_col[pc])
    else:
        out_rows = []
    print(f"Col {pc:2d}: {inp_rows} -> {out_rows}")

# Let me look at this more carefully
# Each 2 moves vertically to some target row in the same column
# But when multiple 2s go to the same target, some disappear

# Let me verify that ALL movements are vertical
horizontal_moves = []
for pr, pc in input_positions:
    output_rows_in_col = [or_ for or_, oc in output_positions if oc == pc]
    for or_ in output_rows_in_col:
        if or_ == pr:
            break
    else:
        horizontal_moves.append((pr, pc, output_rows_in_col))

if horizontal_moves:
    print("Some 2s may have horizontal movement:")
    for pr, pc, or_list in horizontal_moves[:5]:
        print(f"  ({pr},{pc}): output rows in col {pc}: {or_list}")
else:
    print("Verified: All 2s move vertically to some row in the same column!")

# Now let me see the mapping within each column
print("\n\nColumn-by-column mapping:")
for pc in sorted(input_by_col.keys()):
    inp_rows = sorted(input_by_col[pc])
    # Sort output rows by how far they need to travel
    if pc in output_by_col:
        out_rows = sorted(output_by_col[pc])
    else:
        out_rows = []
    print(f"Col {pc:2d}: input rows {inp_rows} -> output rows {out_rows}")

